add_action( 'woocommerce_order_status_completed', 'perfectpixel_vip_role_by_total_spent', 20, 2 );

function perfectpixel_vip_role_by_total_spent( $order_id, $order = null ) {
	$order   = $order ? $order : wc_get_order( $order_id );
	$user_id = $order ? $order->get_customer_id() : 0;
	$role    = get_role( sanitize_key( '{{vip_role}}' ) );
	if ( ! $user_id || ! $role || $role->has_cap( 'edit_posts' ) || $role->has_cap( 'manage_woocommerce' ) ) {
		return;
	}
	$user = get_userdata( $user_id );
	// Only promote plain customers (never touch admins, shop managers, etc.).
	if ( ! $user || ! in_array( 'customer', (array) $user->roles, true ) ) {
		return;
	}
	if ( (float) wc_get_customer_total_spent( $user_id ) >= (float) '{{vip_spent_threshold}}' ) {
		$user->set_role( $role->name );
		$order->add_order_note( sprintf( 'Ο πελάτης έγινε «%s» (σύνολο αγορών πάνω από το όριο).', $role->name ), false, true );
	}
}
